CREATE TYPE "OrganizationRole" AS ENUM ('owner', 'admin', 'member', 'viewer');
CREATE TYPE "ScanStatus" AS ENUM ('queued', 'running', 'completed', 'failed', 'cancelled');

CREATE TABLE "User" ("id" TEXT PRIMARY KEY, "githubId" TEXT UNIQUE, "email" TEXT UNIQUE, "name" TEXT, "avatarUrl" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Organization" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "slug" TEXT NOT NULL UNIQUE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "OrganizationMember" ("id" TEXT PRIMARY KEY, "organizationId" TEXT NOT NULL, "userId" TEXT NOT NULL, "role" "OrganizationRole" NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "OrganizationMember_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE, CONSTRAINT "OrganizationMember_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "OrganizationMember_organizationId_userId_key" ON "OrganizationMember"("organizationId","userId"); CREATE INDEX "OrganizationMember_userId_idx" ON "OrganizationMember"("userId");
CREATE TABLE "Project" ("id" TEXT PRIMARY KEY, "organizationId" TEXT NOT NULL, "name" TEXT NOT NULL, "slug" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Project_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "Project_organizationId_slug_key" ON "Project"("organizationId","slug"); CREATE INDEX "Project_organizationId_idx" ON "Project"("organizationId");
CREATE TABLE "Domain" ("id" TEXT PRIMARY KEY, "projectId" TEXT NOT NULL, "hostname" TEXT NOT NULL, "verifiedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Domain_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "Domain_projectId_hostname_key" ON "Domain"("projectId","hostname"); CREATE INDEX "Domain_projectId_idx" ON "Domain"("projectId");
CREATE TABLE "DomainVerification" ("id" TEXT PRIMARY KEY, "domainId" TEXT NOT NULL, "tokenHash" TEXT NOT NULL, "tokenPrefix" TEXT NOT NULL, "method" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "verifiedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "DomainVerification_domainId_fkey" FOREIGN KEY ("domainId") REFERENCES "Domain"("id") ON DELETE CASCADE);
CREATE INDEX "DomainVerification_domainId_expiresAt_idx" ON "DomainVerification"("domainId","expiresAt");
CREATE TABLE "Scan" ("id" TEXT PRIMARY KEY, "projectId" TEXT NOT NULL, "targetKind" TEXT NOT NULL, "targetValue" TEXT NOT NULL, "status" "ScanStatus" NOT NULL, "score" DOUBLE PRECISION NOT NULL, "schemaVersion" TEXT NOT NULL, "summaryJson" JSONB NOT NULL, "modulesJson" JSONB NOT NULL, "errorsJson" JSONB NOT NULL, "startedAt" TIMESTAMP(3) NOT NULL, "completedAt" TIMESTAMP(3) NOT NULL, "durationMs" INTEGER NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Scan_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE);
CREATE INDEX "Scan_projectId_completedAt_idx" ON "Scan"("projectId","completedAt" DESC); CREATE INDEX "Scan_projectId_score_idx" ON "Scan"("projectId","score");
CREATE TABLE "Finding" ("id" TEXT PRIMARY KEY, "projectId" TEXT NOT NULL, "fingerprint" TEXT NOT NULL, "ruleId" TEXT NOT NULL, "title" TEXT NOT NULL, "description" TEXT NOT NULL, "severity" TEXT NOT NULL, "category" TEXT NOT NULL, "confidence" TEXT NOT NULL, "source" TEXT NOT NULL, "remediation" TEXT, "documentationUrl" TEXT, "firstDetectedAt" TIMESTAMP(3) NOT NULL, "lastDetectedAt" TIMESTAMP(3) NOT NULL, "status" TEXT NOT NULL DEFAULT 'open', CONSTRAINT "Finding_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "Finding_projectId_fingerprint_key" ON "Finding"("projectId","fingerprint"); CREATE INDEX "Finding_projectId_severity_status_idx" ON "Finding"("projectId","severity","status"); CREATE INDEX "Finding_ruleId_idx" ON "Finding"("ruleId");
CREATE TABLE "FindingOccurrence" ("id" TEXT PRIMARY KEY, "findingId" TEXT NOT NULL, "scanId" TEXT NOT NULL, "file" TEXT, "line" INTEGER, "column" INTEGER, "url" TEXT, "evidenceJson" JSONB, "severity" TEXT NOT NULL, "observedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "FindingOccurrence_findingId_fkey" FOREIGN KEY ("findingId") REFERENCES "Finding"("id") ON DELETE CASCADE, CONSTRAINT "FindingOccurrence_scanId_fkey" FOREIGN KEY ("scanId") REFERENCES "Scan"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "FindingOccurrence_findingId_scanId_key" ON "FindingOccurrence"("findingId","scanId"); CREATE INDEX "FindingOccurrence_scanId_idx" ON "FindingOccurrence"("scanId");
CREATE TABLE "Suppression" ("id" TEXT PRIMARY KEY, "projectId" TEXT NOT NULL, "ruleId" TEXT, "fingerprint" TEXT, "reason" TEXT NOT NULL, "expiresAt" TIMESTAMP(3), "createdBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Suppression_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE);
CREATE INDEX "Suppression_projectId_expiresAt_idx" ON "Suppression"("projectId","expiresAt");
CREATE TABLE "ExternalDomain" ("id" TEXT PRIMARY KEY, "projectId" TEXT NOT NULL, "scanId" TEXT, "domain" TEXT NOT NULL, "classification" TEXT NOT NULL, "resourceTypes" TEXT[] NOT NULL, "firstSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "lastSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ExternalDomain_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE, CONSTRAINT "ExternalDomain_scanId_fkey" FOREIGN KEY ("scanId") REFERENCES "Scan"("id") ON DELETE SET NULL);
CREATE UNIQUE INDEX "ExternalDomain_projectId_domain_key" ON "ExternalDomain"("projectId","domain"); CREATE INDEX "ExternalDomain_scanId_idx" ON "ExternalDomain"("scanId");
CREATE TABLE "Route" ("id" TEXT PRIMARY KEY, "projectId" TEXT NOT NULL, "scanId" TEXT, "method" TEXT NOT NULL, "url" TEXT NOT NULL, "status" INTEGER, "contentType" TEXT, "cors" TEXT, "authObservable" BOOLEAN, "firstSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "lastSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Route_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE, CONSTRAINT "Route_scanId_fkey" FOREIGN KEY ("scanId") REFERENCES "Scan"("id") ON DELETE SET NULL);
CREATE UNIQUE INDEX "Route_projectId_method_url_key" ON "Route"("projectId","method","url"); CREATE INDEX "Route_scanId_idx" ON "Route"("scanId");
CREATE TABLE "Deployment" ("id" TEXT PRIMARY KEY, "projectId" TEXT NOT NULL, "environment" TEXT NOT NULL, "url" TEXT NOT NULL, "commitSha" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Deployment_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE); CREATE INDEX "Deployment_projectId_createdAt_idx" ON "Deployment"("projectId","createdAt" DESC);
CREATE TABLE "Integration" ("id" TEXT PRIMARY KEY, "projectId" TEXT NOT NULL, "type" TEXT NOT NULL, "configJson" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Integration_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE); CREATE INDEX "Integration_projectId_idx" ON "Integration"("projectId");
CREATE TABLE "ApiKey" ("id" TEXT PRIMARY KEY, "organizationId" TEXT NOT NULL, "name" TEXT NOT NULL, "prefix" TEXT NOT NULL UNIQUE, "keyHash" TEXT NOT NULL, "createdBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "lastUsedAt" TIMESTAMP(3), "revokedAt" TIMESTAMP(3), CONSTRAINT "ApiKey_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE); CREATE INDEX "ApiKey_organizationId_revokedAt_idx" ON "ApiKey"("organizationId","revokedAt");
